  .asset-list {
    grid-template-columns: repeat(auto-fill, minmax(44px, 1fr));
  }
}

@media (max-width: 560px) {
  .topbar {
    height: auto;
    align-items: start;
    flex-direction: column;
  }

  .workspace {
    padding: 10px;
    gap: 10px;
  }

  .asset-list {
    grid-template-columns: repeat(auto-fill, minmax(42px, 1fr));
  }

  .asset-card img {
    max-width: 38px;
    max-height: 38px;
  }

  .statusbar {
    align-items: start;
    flex-direction: column;
  }
}

